package com.example.jmx;

import javax.management.MBeanServer;
import javax.management.ObjectName;
import java.lang.management.ManagementFactory;

/**
 * Main application that exposes system information via JMX.
 *
 * This application registers a custom MBean with the platform MBean server,
 * allowing you to monitor and manage the application using JMX tools like
 * JConsole or VisualVM.
 */
public class App {

    public static void main(String[] args) {
        try {
            // Get the platform MBean server
            MBeanServer mBeanServer = ManagementFactory.getPlatformMBeanServer();

            // Create the MBean instance
            SystemInfo systemInfo = new SystemInfo();

            // Create a unique ObjectName for our MBean
            // Format: domain:key1=value1,key2=value2
            ObjectName objectName = new ObjectName("com.example.jmx:type=SystemInfo");

            // Register the MBean
            mBeanServer.registerMBean(systemInfo, objectName);

            System.out.println("========================================");
            System.out.println("JMX POC Application Started Successfully");
            System.out.println("========================================");
            System.out.println();
            System.out.println("MBean registered: " + objectName);
            System.out.println();
            System.out.println("You can now connect to this application using:");
            System.out.println("  - JConsole");
            System.out.println("  - VisualVM");
            System.out.println("  - Any other JMX client");
            System.out.println();
            System.out.println("To connect:");
            System.out.println("  1. Run 'jconsole' in a terminal");
            System.out.println("  2. Select this process from the local processes list");
            System.out.println("  3. Go to the 'MBeans' tab");
            System.out.println("  4. Navigate to: com.example.jmx -> SystemInfo");
            System.out.println();
            System.out.println("Available attributes and operations:");
            System.out.println("  - AvailableProcessors (attribute)");
            System.out.println("  - TotalMemory (attribute)");
            System.out.println("  - FreeMemory (attribute)");
            System.out.println("  - UsedMemory (attribute)");
            System.out.println("  - Uptime (attribute)");
            System.out.println("  - ApplicationMessage (read/write attribute)");
            System.out.println("  - triggerGarbageCollection() (operation)");
            System.out.println("  - getMemoryInfo() (operation)");
            System.out.println();
            System.out.println("Application is running. Press Ctrl+C to exit.");
            System.out.println("========================================");

            // Keep the application running
            // This prevents the JVM from exiting so JMX clients can connect
            Thread.currentThread().join();

        } catch (Exception e) {
            System.err.println("Error starting JMX application: " + e.getMessage());
            e.printStackTrace();
            System.exit(1);
        }
    }
}
